describe('Empty State - No Notifications', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display empty state when no notifications exist', () => {
    // Intercept the API call to return an empty array
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: []
    }).as('getNotifications');

    cy.wait('@getNotifications');

    // Verify the empty state message is visible
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'You have no notifications');

    // Verify the notification list is empty
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Verify the empty state icon is displayed
    cy.get('[data-testid="empty-state-icon"]').should('be.visible');
  });

  it('should hide empty state when notifications are added', () => {
    // Intercept the API call to return an empty array initially
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: []
    }).as('getNotificationsEmpty');

    cy.wait('@getNotificationsEmpty');

    // Verify empty state is visible initially
    cy.get('[data-testid="empty-state-message"]').should('be.visible');

    // Intercept the API call to return a notification
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: [
        {
          id: 1,
          type: 'like',
          message: 'Someone liked your post',
          timestamp: '2023-10-27T10:00:00Z'
        }
      ]
    }).as('getNotificationsWithItems');

    // Trigger refresh or navigate to reload notifications
    cy.reload();
    cy.wait('@getNotificationsWithItems');

    // Verify empty state is no longer visible
    cy.get('[data-testid="empty-state-message"]').should('not.exist');

    // Verify notification list is visible and contains items
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'Someone liked your post');
  });
});
